package cn.mop.api;
import cn.mop.domain.*;
import cn.mop.domain.inspection.*;
import cn.mop.domain.inspection.InspectionSourceCollectionRepository.*;
import cn.mop.persistence.InspectionSourceDocumentCodec;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.node.*;
import org.junit.jupiter.api.*;
import org.mockito.ArgumentCaptor;
import org.springframework.mock.web.MockHttpServletRequest;
import java.nio.charset.StandardCharsets;
import java.time.Instant;
import java.security.MessageDigest;
import java.util.*;
import java.util.function.Supplier;
import static cn.mop.api.InspectionWorksheetControllerTest.*;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
/** Isolated input/projection tests only. Real HTTP/PG/CSRF checks are recorded separately. */
class InspectionSourceCollectionControllerTest {
    static final String COLLECTION="78000000-0000-4000-8000-000000000009";
    PlatformRepository platform;InspectionSourceCollectionRepository repository;InspectionSourceCollectionController controller;final ObjectMapper mapper=new ObjectMapper();InspectionSourceSnapshot source;InspectionSourceManifest manifest;Summary summary;
    @BeforeEach void setup()throws Exception{
        platform=mock(PlatformRepository.class);repository=mock(InspectionSourceCollectionRepository.class);controller=new InspectionSourceCollectionController(platform,repository);when(platform.membership(ACTOR,TENANT)).thenReturn(Optional.of(new Membership(ACTOR,TENANT,"padmin",7,true)));when(platform.idempotentAuthorized(any(),any(),any(),any(),any(),anyLong(),any(),any())).thenAnswer(call->{((Runnable)call.getArgument(6)).run();return ((Supplier<?>)call.getArgument(7)).get();});
        var f=new InspectionWorksheetControllerTest();source=InspectionSourceSnapshot.fromEntry(f.row(1,"CREATE",false,new InspectionWorksheetRepository.Content(Map.of(),null),f.definition()));manifest=new InspectionSourceManifest(UUID.fromString(TENANT),List.of(source));summary=new Summary(COLLECTION,TENANT,ACTOR,Instant.parse("2026-10-04T10:00:00Z"),1,"合成来源",1,HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(InspectionSourceDocumentCodec.encode(manifest))),manifest.fingerprint());when(repository.create(any(),anyLong(),any())).thenReturn(summary);when(repository.get(any(),eq(COLLECTION))).thenReturn(new Stored(summary,manifest));when(repository.list(any(),anyInt(),any(),any())).thenReturn(List.of(summary));
    }
    Access access(){return new Access(ACTOR,TENANT,7,"source-collection-test");}
    MockHttpServletRequest request(String method){var r=new MockHttpServletRequest(method,"/api/v1/inspection-source-collections");r.setUserPrincipal(()->ACTOR);r.getSession().setAttribute("mop.tenant_id",TENANT);r.setAttribute("mop.trace_id","source-collection-test");r.addHeader("Idempotency-Key","collection-test");return r;}
    ObjectNode input(){var v=mapper.createObjectNode().put("expected_version",0).put("label","合成来源");v.putArray("sources").addObject().put("worksheet_id",ID).put("version",1).put("expected_source_sha256",source.fingerprint());return v;}
    Map<?,?> data(Object v){return (Map<?,?>)((Map<?,?>)v).get("data");}
    @Test void creationRequiresExplicitSourceHashAndReturnsSmallUnpublishedMetadata(){var result=data(controller.write(input(),request("POST")));assertEquals(COLLECTION,result.get("id"));assertEquals("METADATA_ONLY",result.get("projection"));assertEquals(false,result.get("formal_report_generatable"));assertEquals(false,result.get("report_published"));assertEquals("CONFIG_PENDING",result.get("generation_status"));assertNull(result.get("tenant_asset_population"));assertNull(result.get("period_time_zone"));assertFalse(result.containsKey("sources"));assertFalse(result.containsKey("document_integrity"));verify(repository).authorizeWrite(access());var capture=ArgumentCaptor.forClass(Creation.class);verify(repository).create(eq(access()),eq(0L),capture.capture());assertEquals(source.fingerprint(),capture.getValue().sources().get(0).expectedSourceSha256());}
    @Test void completeDetailPreservesSourceFactsAndUnknownDiagnostics(){var result=data(controller.get(COLLECTION,request("GET")));assertEquals("FULL_SOURCES",result.get("projection"));assertEquals("VERIFIED_SERVER_SIDE",result.get("document_integrity"));var sources=(List<?>)result.get("sources");assertEquals(1,sources.size());var entry=(Map<?,?>)sources.get(0);assertEquals(ID,entry.get("worksheet_id"));assertFalse(entry.containsKey("updated_at"));assertNull(entry.get("reported_performed_at"));var diagnostics=(Map<?,?>)result.get("diagnostics");assertEquals(1,((List<?>)diagnostics.get("unknown_inspection_time")).size());assertEquals(1,((List<?>)diagnostics.get("incompletely_entered")).size());assertTrue(((List<?>)diagnostics.get("assets_with_multiple_sources")).isEmpty());verify(platform,never()).idempotentAuthorized(any(),any(),any(),any(),any(),anyLong(),any(),any());}
    @Test void unknownReadAndWriteQueriesCannotOverrideTenant(){for(String method:List.of("GET","POST")){var r=request(method);r.addParameter("tenant_id",TENANT);assertEquals(400,assertThrows(DomainException.class,()->{if(method.equals("GET"))controller.list(r);else controller.write(input(),r);}).status);}verifyNoInteractions(repository);}
    @Test void foreignRoleFailsBeforeMalformedBodyParsing(){for(String role:List.of("viewer","msp","tadmin","unknown")){when(platform.membership(ACTOR,TENANT)).thenReturn(Optional.of(new Membership(ACTOR,TENANT,role,7,true)));var r=request("POST");r.setContent("invalid".getBytes(StandardCharsets.UTF_8));assertEquals(403,assertThrows(DomainException.class,()->controller.create(r)).status);assertEquals(403,assertThrows(DomainException.class,()->controller.get("bad",request("GET"))).status);}verifyNoInteractions(repository);}
    @Test void missingInactiveOrMalformedSessionFails(){var r=request("GET");r.setUserPrincipal(null);assertEquals(401,assertThrows(DomainException.class,()->controller.list(r)).status);r.setUserPrincipal(()->ACTOR);r.getSession().setAttribute("mop.tenant_id",42);assertEquals(401,assertThrows(DomainException.class,()->controller.list(r)).status);when(platform.membership(ACTOR,TENANT)).thenReturn(Optional.of(new Membership(ACTOR,TENANT,"padmin",7,false)));assertEquals(401,assertThrows(DomainException.class,()->controller.list(request("GET"))).status);verifyNoInteractions(repository);}
    @Test void expectedVersionExactFieldsAndNoReportOverrides(){for(JsonNode v:List.of(IntNode.valueOf(1),IntNode.valueOf(-1),TextNode.valueOf("0"),DoubleNode.valueOf(0.0))){var x=input();x.set("expected_version",v);assertEquals(400,assertThrows(DomainException.class,()->controller.write(x,request("POST"))).status);}for(String key:List.of("expected_version","label","sources")){var x=input();x.remove(key);assertEquals(400,assertThrows(DomainException.class,()->controller.write(x,request("POST"))).status);}for(String key:List.of("tenant_id","report_published","period_time_zone","quarter_selection_rule","summary","document_sha256"))assertEquals(400,assertThrows(DomainException.class,()->controller.write(input().put(key,"forged"),request("POST"))).status);verifyNoInteractions(repository);}
    @Test void sourcesNeedExactFieldsCanonicalHashAndValidExplicitVersion(){for(String key:List.of("worksheet_id","version","expected_source_sha256")){var x=input();((ObjectNode)x.path("sources").get(0)).remove(key);assertThrows(DomainException.class,()->controller.write(x,request("POST")));}for(String hash:List.of("a".repeat(63),"A".repeat(64),"g".repeat(64))){var x=input();((ObjectNode)x.path("sources").get(0)).put("expected_source_sha256",hash);assertThrows(DomainException.class,()->controller.write(x,request("POST")));}for(JsonNode v:List.of(IntNode.valueOf(0),LongNode.valueOf(9007199254740991L),TextNode.valueOf("1"),DoubleNode.valueOf(1.0))){var x=input();((ObjectNode)x.path("sources").get(0)).set("version",v);assertThrows(DomainException.class,()->controller.write(x,request("POST")));}var x=input();((ObjectNode)x.path("sources").get(0)).put("latest",true);assertThrows(DomainException.class,()->controller.write(x,request("POST")));verifyNoInteractions(repository);}
    @Test void duplicateSourcesAreRejectedAndEmptySelectionNotAutoFilled(){var duplicate=input();((ArrayNode)duplicate.get("sources")).add(duplicate.path("sources").get(0).deepCopy());assertThrows(DomainException.class,()->controller.write(duplicate,request("POST")));var empty=input();empty.putArray("sources");controller.write(empty,request("POST"));verify(repository).create(eq(access()),eq(0L),eq(new Creation("合成来源",List.of())));}
    @Test void nullWrongTypesAndOverThousandSourcesFail()throws Exception{for(String raw:List.of("null","{}","[null]","[42]")){var x=input();x.set("sources",mapper.readTree(raw));assertThrows(DomainException.class,()->controller.write(x,request("POST")));}var x=input();var rows=(ArrayNode)x.get("sources");var row=rows.get(0);for(int i=0;i<1000;i++)rows.add(row.deepCopy());assertEquals(413,assertThrows(DomainException.class,()->controller.write(x,request("POST"))).status);verifyNoInteractions(repository);}
    @Test void originalReceiptRechecksAuthorizationWithoutRecreating(){doAnswer(call->{((Runnable)call.getArgument(6)).run();return Map.of("original",true);}).when(platform).idempotentAuthorized(any(),any(),any(),any(),any(),anyLong(),any(),any());assertEquals(true,data(controller.write(input(),request("POST"))).get("original"));verify(repository).authorizeWrite(access());verify(repository,never()).create(any(),anyLong(),any());}
    @Test void hashIgnoresObjectOrderButRetainsArrayOrderAndLabel()throws Exception{var a=input();var b=(ObjectNode)mapper.readTree("{\"sources\":[{\"expected_source_sha256\":\""+source.fingerprint()+"\",\"version\":1,\"worksheet_id\":\""+ID+"\"}],\"label\":\"合成来源\",\"expected_version\":0}");var c=a.deepCopy().put("label","合成来源2");var d=a.deepCopy();((ArrayNode)d.get("sources")).addObject().put("worksheet_id",UUID.randomUUID().toString()).put("version",2).put("expected_source_sha256","a".repeat(64));var e=d.deepCopy();var arr=e.putArray("sources");arr.add(d.path("sources").get(1));arr.add(d.path("sources").get(0));for(var x:List.of(a,b,c,d,e))controller.write(x,request("POST"));var hashes=ArgumentCaptor.forClass(String.class);verify(platform,times(5)).idempotentAuthorized(any(),any(),any(),any(),hashes.capture(),anyLong(),any(),any());var h=hashes.getAllValues();assertEquals(h.get(0),h.get(1));assertNotEquals(h.get(0),h.get(2));assertNotEquals(h.get(3),h.get(4));}
    @Test void listUsesLookAheadAndPairedCursorWithoutFullDocument(){when(repository.list(eq(access()),eq(16),isNull(),isNull())).thenReturn(Collections.nCopies(16,summary));var d=data(controller.list(request("GET")));assertEquals(15,((List<?>)d.get("items")).size());assertEquals(true,d.get("has_more"));assertEquals(COLLECTION,d.get("next_before_id"));assertEquals(summary.recordedAt().toString(),d.get("next_before_recorded_at"));var next=request("GET");next.addParameter("page_size","10");next.addParameter("before_recorded_at",summary.recordedAt().toString());next.addParameter("before_id",COLLECTION);controller.list(next);verify(repository).list(access(),11,summary.recordedAt(),COLLECTION);verify(repository,never()).get(any(),any());}
    @Test void malformedOrRepeatedQueryBoundsFail(){var a=request("GET");a.addParameter("page_size","10","15");var b=request("GET");b.addParameter("before_id",COLLECTION);var c=request("GET");c.addParameter("page_size","21");var d=request("GET");d.addParameter("before_recorded_at","2026-01-01");d.addParameter("before_id",COLLECTION);for(var r:List.of(a,b,c,d))assertThrows(DomainException.class,()->controller.list(r));verifyNoInteractions(repository);}
    @Test void bodyRejectsDuplicateTrailingDeepAndOversizeJson()throws Exception{for(String raw:List.of("null","{\"label\":\"a\",\"label\":\"b\"}","{} {}","[[[[[{}]]]]]")){var r=request("POST");r.setContent(raw.getBytes(StandardCharsets.UTF_8));assertThrows(DomainException.class,()->controller.create(r));}var r=request("POST");r.setContent(new byte[InspectionSourceCollectionController.MAX_BODY_BYTES+1]);assertEquals(413,assertThrows(DomainException.class,()->controller.create(r)).status);verifyNoInteractions(repository);}
    @Test void legalThousandSourceBodyWithinTechnicalBudgetIsAccepted()throws Exception{var x=input();var rows=x.putArray("sources");for(int i=0;i<1000;i++)rows.addObject().put("worksheet_id",new UUID(0,i+1).toString()).put("version",1).put("expected_source_sha256","a".repeat(64));x.put("label","😀".repeat(200));var r=request("POST");var bytes=x.toString().getBytes(StandardCharsets.UTF_8);assertTrue(bytes.length<InspectionSourceCollectionController.MAX_BODY_BYTES);r.setContent(bytes);controller.create(r);var capture=ArgumentCaptor.forClass(Creation.class);verify(repository).create(eq(access()),eq(0L),capture.capture());assertEquals(1000,capture.getValue().sources().size());}
    @Test void missingIdempotencyKeyPreventsMutation(){var r=request("POST");r.removeHeader("Idempotency-Key");assertThrows(DomainException.class,()->controller.write(input(),r));verifyNoInteractions(repository);}
    @Test void repoErrorsAndUnexpectedReadScopeNeverFallback(){for(int status:new int[]{401,403,404,409,503}){doThrow(new DomainException(status,"SYNTHETIC","test")).when(repository).get(any(),any());assertEquals(status,assertThrows(DomainException.class,()->controller.get(COLLECTION,request("GET"))).status);}reset(repository);when(repository.get(any(),any())).thenReturn(new Stored(summary,new InspectionSourceManifest(UUID.fromString(TENANT),List.of())));assertEquals(503,assertThrows(DomainException.class,()->controller.get(COLLECTION,request("GET"))).status);when(repository.get(any(),any())).thenReturn(new Stored(new Summary(summary.id(),ASSET,summary.createdBy(),summary.recordedAt(),1,summary.label(),1,summary.documentSha256(),summary.sourceManifestSha256()),manifest));assertEquals(503,assertThrows(DomainException.class,()->controller.get(COLLECTION,request("GET"))).status);verify(repository,never()).create(any(),anyLong(),any());}
}
